(function(){
 'use strict';
 const M=ParentModel,units=window.REVIEW_UNITS,bank=new Map(units.flatMap(u=>u.questions).concat(window.REVIEW_EXAM_ITEMS||[]).map(q=>[q.id,q])),active=units.filter(u=>u.active!==false),$=s=>document.querySelector(s),esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
 let imported=[],cloud=[],local=[],busy=false,sourceNote='',wrongLimit=30,wrongQuery='',wrongMode='open',historyLimit=30;
 const read=(k,f)=>{try{return JSON.parse(localStorage.getItem(k))??f;}catch{return f;}},date=s=>{const d=new Date(s);return Number.isFinite(+d)?d.toLocaleString('zh-TW',{timeZone:'Asia/Taipei',month:'2-digit',day:'2-digit',hour:'2-digit',minute:'2-digit'}):'時間未提供';};
 const list=a=>Array.isArray(a)?a.join('\n'):String(a??''),rate=(a,b)=>b?Math.round(a/b*100)+'％':'—';
 function loadLocal(){local=M.merge(...read('little-study-names-v3',[]).filter(n=>typeof n==='string').map(n=>read('little-study-v3:'+encodeURIComponent(n)+':records',[])));}
 function all(){return M.merge(local,imported,cloud);}
 function options(){const prev=$('#child').value,names=[...new Set(all().map(e=>e.learner))].sort();$('#child').innerHTML=names.length?names.map(n=>`<option>${esc(n)}</option>`).join(''):'<option value="">尚無孩子紀錄</option>';if(names.includes(prev))$('#child').value=prev;const s=$('#subject').value;$('#subject').innerHTML='<option value="">全部科目</option>'+[...new Set(active.map(u=>u.subject))].map(n=>`<option>${esc(n)}</option>`).join('');$('#subject').value=s;}
 function filtered(){const days=Number($('#period').value),cutoff=Date.now()-days*86400000;return all().filter(e=>e.learner===$('#child').value&&(!$('#grade').value||M.grade(e,units)===Number($('#grade').value))&&(!$('#subject').value||e.subject===$('#subject').value)&&(!days||new Date(e.createdAt).getTime()>=cutoff));}
 function render(){
 const events=filtered(),s=M.summary(events),grades=new Set(events.map(e=>M.grade(e,units))),scope=active.filter(u=>(!$('#grade').value?grades.has(u.grade):u.grade===Number($('#grade').value))&&(!$('#subject').value||u.subject===$('#subject').value));
 $('#status').textContent=`本機 ${local.length} 筆・CSV ${imported.length} 筆・雲端 ${cloud.length} 筆（重複編號合併）。${sourceNote||'本機資料限這個瀏覽器；其他裝置請匯入 CSV 或連線雲端。'}`;
 if(!events.length){$('#report').innerHTML='<section class="panel empty"><h3>這裡會呈現孩子的學習足跡</h3><p>目前篩選條件下沒有作答紀錄。可調整孩子、年級或期間，或從「資料與雲端連線」匯入紀錄。</p><button id="empty-source">選擇紀錄來源</button></section>';$('#empty-source').onclick=()=>$('#source-dialog').showModal();return;}
 const touched=scope.filter(u=>s.answers.some(e=>u.questions.some(q=>q.id===e.questionId)||bank.get(e.questionId)?.unit===u.id)).length;
 $('#report').innerHTML=`<div class="cards"><article class="card">練習足跡<strong>${touched}<small> / ${scope.length} 單元</small></strong><small>期間內曾作答的單元，非精熟認證</small></article><article class="card">完成練習<strong>${s.sessions.length}<small> 次</small></strong><small>${s.days} 天有作答・共 ${s.answers.length} 次答題</small></article><article class="card">作答正確率<strong>${s.accuracy??'—'}<small>％</small></strong><small>逐題次數統計，重做題也計入</small></article><article class="card">待複習錯題<strong>${s.open.length}<small> 題</small></strong><small>曾答錯且最後一次仍答錯</small></article></div><div class="grid"><section class="panel"><h3>各單元複習進度</h3><p class="hint">題庫覆蓋率＝期間內作答過的不同題目／目前題庫題數。模擬考題目歸回所屬單元；停用範圍的舊紀錄保留於歷程。</p><div class="scroll"><table><thead><tr><th>單元</th><th>題庫覆蓋</th><th>正確率</th><th>待複習</th><th>最近作答</th></tr></thead><tbody>${scope.map(u=>{const rows=s.answers.filter(e=>bank.get(e.questionId)?.unit===u.id),ids=new Set(rows.map(e=>e.questionId)),covered=u.questions.filter(q=>ids.has(q.id)).length,w=s.open.filter(w=>bank.get(w.latest.questionId)?.unit===u.id).length;return `<tr><td class="unit-name">${u.grade===3?'三上':'五上'}・${esc(u.subject)}<br><b>${esc(u.name)}</b></td><td><progress max="${u.questions.length}" value="${covered}" aria-label="${esc(u.name)}題庫覆蓋率"></progress><small>${covered} / ${u.questions.length} 題</small></td><td>${rate(rows.filter(e=>e.correct).length,rows.length)}</td><td>${w?`<button data-unit="${u.id}">${w} 題</button>`:'—'}</td><td>${rows.length?date(rows.at(-1).createdAt):'尚未練習'}</td></tr>`;}).join('')}</tbody></table></div></section><section class="panel"><h3>最近成績趨勢</h3><p class="hint">最近 ${Math.min(s.sessions.length,10)} 份完成練習，依時間排列。模擬考採原配分，練習採答對比例。</p>${s.sessions.length?`<div class="trend" role="img" aria-label="最近練習分數：${s.sessions.slice(-10).map(e=>esc(e.score)+' 分').join('、')}">${s.sessions.slice(-10).map(e=>`<div title="${esc(e.unitName)}・${date(e.createdAt)}・${esc(e.score)} 分"><b>${esc(e.score)}</b><i style="height:${Math.max(0,Math.min(100,Number(e.score)||0))*1.1}px"></i><time>${date(e.createdAt).split(' ')[0]}</time></div>`).join('')}</div>`:'<p class="empty">完成整份練習後才會顯示成績；已作答的題目仍會列入進度。</p>'}</section></div><section class="panel" id="wrong-panel"><h3>錯題觀察與解析</h3><p class="hint">「已再答對」表示最後一次作答正確，仍可定期複習。每題可展開查看孩子的答案、正確答案與歷次作答。</p><div class="tools"><select id="wrong-mode" aria-label="錯題狀態"><option value="open">待複習</option><option value="resolved">已再答對</option><option value="all">所有曾錯題</option></select><input id="wrong-search" aria-label="搜尋錯題" placeholder="搜尋題目、單元或題號"></div><div id="wrong-list"></div></section><section class="panel"><h3>完整練習歷程</h3><p class="hint">顯示已完成的練習；展開可看該份紀錄中的每道題目。未完成練習的答題仍列入上方進度及錯題。</p><div id="sessions"></div></section>`;
 $('#wrong-mode').value=wrongMode;$('#wrong-search').value=wrongQuery;$('#wrong-mode').onchange=e=>{wrongMode=e.target.value;wrongLimit=30;renderWrong(s);};$('#wrong-search').oninput=e=>{wrongQuery=e.target.value;wrongLimit=30;renderWrong(s);};renderWrong(s);renderSessions(s);document.querySelectorAll('[data-unit]').forEach(b=>b.onclick=()=>{wrongMode='open';wrongQuery=units.find(u=>u.id===Number(b.dataset.unit)).name;$('#wrong-mode').value=wrongMode;$('#wrong-search').value=wrongQuery;renderWrong(s);$('#wrong-panel').scrollIntoView({behavior:'smooth'});});
 }
 function detail(e){const q=bank.get(e.questionId),visual=q&&window.LearningVisuals?LearningVisuals.markup(q):'';return `<p class="hint">${esc(e.subject)}・${esc(e.unitName)}・${esc(e.questionId)}・${date(e.createdAt)}</p>${visual}<div class="question">${esc(e.question||q?.text||'未保存題幹')}</div><div class="answers"><div><b>孩子的作答</b><p>${esc(list(e.selected))}</p></div><div><b>當時的正確答案</b><p>${esc(list(e.expected))}</p></div></div>${q?`<p><b>目前題庫解析：</b>${esc(q.explanation||'未提供')}</p><p class="hint">配圖與解析取自目前題庫；當時作答及答案以紀錄為準。</p>`:''}`;}
 function wireDetails(container,lookup){container.querySelectorAll('details[data-key]').forEach(d=>d.addEventListener('toggle',()=>{if(d.open&&!d.dataset.loaded){d.querySelector('.detail-body').innerHTML=lookup(Number(d.dataset.key));d.dataset.loaded='1';}}));}
 function renderWrong(s){const items=s.wrong.filter(w=>(wrongMode==='all'||(wrongMode==='resolved'?w.resolved:!w.resolved))&&[w.latest.question,w.latest.unitName,w.latest.questionId].join(' ').toLowerCase().includes(wrongQuery.toLowerCase())).sort((a,b)=>b.count-a.count||String(b.latest.createdAt).localeCompare(String(a.latest.createdAt)));const el=$('#wrong-list');el.innerHTML=`<p class="hint">共 ${items.length} 題，先顯示答錯次數較多的題目。</p>`+items.slice(0,wrongLimit).map((w,i)=>`<details data-key="${i}"><summary><span class="tag ${w.resolved?'ok':''}">${w.resolved?'已再答對':'待複習'}・錯 ${w.count} 次</span>${esc(bank.get(w.latest.questionId)?.text||w.latest.question||w.latest.questionId)}</summary><div class="detail-body"></div></details>`).join('')+(items.length>wrongLimit?'<button id="more-wrong">再顯示 30 題</button>':'');wireDetails(el,i=>detail(items[i].latest)+'<h4>這一題的作答足跡</h4>'+items[i].attempts.slice().reverse().map(e=>`<p>${date(e.createdAt)}・${e.correct?'答對':'答錯'}・${esc(list(e.selected))}</p>`).join(''));if($('#more-wrong'))$('#more-wrong').onclick=()=>{wrongLimit+=30;renderWrong(s);};}
 function renderSessions(s){const sessions=s.sessions.slice().reverse(),el=$('#sessions');el.innerHTML=sessions.slice(0,historyLimit).map((e,i)=>`<details data-key="${i}"><summary><span class="tag ${e.score>=80?'ok':''}">${esc(e.score)} 分</span>${esc(e.unitName)}・${esc(e.right)} / ${esc(e.total)} 題・${date(e.createdAt)}</summary><div class="detail-body"></div></details>`).join('')||'<p class="empty">尚無已完成練習。</p>';if(sessions.length>historyLimit)el.insertAdjacentHTML('beforeend','<button id="more-sessions">再顯示 30 份</button>');wireDetails(el,i=>{const a=s.answers.filter(e=>e.sessionId===sessions[i].sessionId);return `<p>用時約 ${Math.round(Number(sessions[i].elapsedSeconds||0)/60)} 分鐘・已讀取 ${a.length} / ${esc(sessions[i].total)} 筆逐題紀錄</p>`+a.map(e=>`<details><summary>${e.correct?'✓ 答對':'○ 答錯'}・${esc(bank.get(e.questionId)?.text||e.question)}</summary>${detail(e)}</details>`).join('');});if($('#more-sessions'))$('#more-sessions').onclick=()=>{historyLimit+=30;renderSessions(s);};}
 function request(token,cursor){return new Promise((resolve,reject)=>{const callback='studyParent_'+Date.now()+'_'+Math.floor(Math.random()*1e8),script=document.createElement('script');const clean=()=>{clearTimeout(timer);script.remove();delete window[callback];};const timer=setTimeout(()=>{clean();reject(Error('雲端讀取逾時，請確認後端已更新部署。'));},30000);window[callback]=r=>{clean();r.ok?resolve(r):reject(Error(r.error||'無法讀取雲端資料'));};script.onerror=()=>{clean();reject(Error('連線失敗，請確認網路與後端部署。'));};const url=new URL(window.LEARNING_CONFIG.gasUrl);url.searchParams.set('action','parent');url.searchParams.set('token',token);url.searchParams.set('cursor',cursor);url.searchParams.set('callback',callback);script.referrerPolicy='no-referrer';script.src=url.href;document.head.appendChild(script);});}
 $('#sources').onclick=()=>$('#source-dialog').showModal();$('#refresh').onclick=()=>{loadLocal();options();render();};for(const id of ['child','grade','subject','period'])$('#'+id).onchange=()=>{wrongLimit=30;historyLimit=30;render();};
 $('#import').onchange=async e=>{const f=e.target.files[0];if(!f)return;try{if(f.size>30*1024*1024)throw Error('檔案超過 30 MB，請先分批匯出。');imported=M.merge(imported,M.fromCSV(await f.text()));options();render();$('#connection').textContent=`已匯入 ${imported.length} 筆紀錄。可關閉此視窗查看。`;}catch(err){$('#connection').textContent=err.message;}e.target.value='';};
 $('#connect').onsubmit=async e=>{e.preventDefault();if(busy)return;busy=true;const button=$('#connect button');button.disabled=true;const token=$('#token').value.trim();$('#token').value='';try{let cursor=2,rows=[],pages=0,snapshot;do{if(++pages>1000)throw Error('資料過多，請改以 CSV 匯入。');$('#connection').textContent=`正在讀取雲端紀錄…已讀取 ${rows.length} 筆`;const r=await request(token,cursor+(snapshot?'_'+snapshot:''));if(!Array.isArray(r.events))throw Error('後端尚未支援家長查詢，請先更新部署。');rows=M.merge(rows,r.events);snapshot=r.end;const next=Number(r.next);if(next&&next<=cursor)throw Error('後端分頁資料異常');cursor=next;}while(cursor);cloud=rows;sourceNote='雲端快照讀取於 '+date(new Date().toISOString())+'；需要最新資料時請重新連線。';options();render();$('#connection').textContent=`雲端已讀取 ${cloud.length} 筆。金鑰不會儲存在網站。`;}catch(err){$('#connection').textContent=err.message;}finally{busy=false;button.disabled=false;}};
 $('#disconnect').onclick=()=>{imported=[];cloud=[];sourceNote='';$('#token').value='';options();render();$('#connection').textContent='已清除匯入與雲端暫存；本機孩子紀錄仍保留。';};window.addEventListener('storage',()=>{loadLocal();options();render();});loadLocal();options();render();
})();
